import {test,expect,type Page} from '@playwright/test';
import fs from 'node:fs';
import {demoCatalog} from '../../src/demo.ts';
import {advance} from '../../src/full/engine.ts';
import {start,snapshot} from './support';
test.use({actionTimeout:8000,navigationTimeout:15000});
async function databases(page:Page){return page.evaluate(()=>indexedDB.databases());}
async function raw(page:Page,name:string){return page.evaluate(name=>new Promise<any>((resolve,reject)=>{const r=indexedDB.open(name);r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,tx=db.transaction([...db.objectStoreNames],'readonly'),out:any={};for(const name of db.objectStoreNames){const s=tx.objectStore(name),keys=s.getAllKeys(),values=s.getAll();values.onsuccess=()=>out[name]={keys:keys.result,values:values.result};}tx.oncomplete=()=>{db.close();resolve(out);};tx.onabort=()=>reject(tx.error);};}),name);}
async function demoGame(page:Page){const id=new URL(page.url()).searchParams.get('demo')!,db=(await databases(page)).find(d=>d.name?.startsWith('chenyuan-demo-game-v1-')&&d.name.endsWith('-'+id));if(!db?.name)return null;const data=await raw(page,db.name);const index=data['full-state'].keys.indexOf('current');return data['full-state'].values[index]??null;}
async function loaded(page:Page,id:string){await page.goto('./?demo='+id);await expect(page.getByTestId('demo-badge')).toBeVisible();await expect(page.getByTestId('save-status')).toHaveText('已保存');await expect(page.locator('[data-session]')).toHaveAttribute('data-session','demo');return demoGame(page);}
async function settings(page:Page){await page.getByRole('button',{name:'设置',exact:true}).click();await expect(page.getByRole('dialog',{name:'行旅设置'})).toBeVisible();}
const normalized=(game:any)=>{const g=structuredClone(game);g.core.runId='<run>';g.core.revision=0;if(g.core.activeEvent)g.core.activeEvent.instanceId='<run>:'+g.core.activeEvent.id;return g;};
for(const node of demoCatalog)test(`demo node ${node.id} loads a lawful playable state in its own database`,async({page})=>{
 const errors:string[]=[];page.on('pageerror',e=>errors.push(e.message));const game=await loaded(page,node.id);expect(game.core.player.name).toBe('演示顾长青');expect(game.school).toBe(node.school);if(node.phase==='battle')await expect(page.getByTestId('attack')).toBeEnabled();if(node.phase==='causal')await expect(page.getByTestId('decide-'+(node.id==='causal-help'?'accept':'bargain'))).toBeEnabled();if(node.phase==='trial')await expect(page.getByTestId('trial-review-entry')).toBeEnabled();if(node.phase==='ending')await expect(page.getByTestId('ending-depart')).toBeEnabled();if(node.phase==='opening')await expect(page.getByTestId('leave')).toBeEnabled();expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1'||d.name==='chenyuan-local-experience-v1')).toBe(false);await settings(page);await expect(page.getByTestId('restore-checkpoint')).toBeDisabled();expect(errors).toEqual([]);
});
test('demo menu, actions, settings and return preserve every normal Game, record and tracking value',async({page,context})=>{
 await start(page);await settings(page);await page.getByLabel('文字大小').selectOption('1.5');await expect(page.getByTestId('local-data-status')).toContainText('已保存');const details=page.getByTestId('local-records-panel');await details.locator('summary').click();await page.getByTestId('local-export-preview').click();await expect(page.getByTestId('local-export-ready')).toBeVisible();await page.getByTestId('local-export-cancel').click();const before=await raw(page,'chenyuan-playable-v1'),local=await raw(page,'chenyuan-local-experience-v1'),tracking=await page.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'));
 await page.getByTestId('demo-menu-open').click();await expect(page.locator('#demo-menu-title')).toBeFocused();const link=await page.getByTestId('demo-node-battle-sword').getAttribute('href');expect(await raw(page,'chenyuan-playable-v1')).toEqual(before);const demo=await context.newPage();try{const first=await loaded(demo,'battle-sword');expect(new URL(link!,page.url()).search).toBe('?demo=battle-sword');await demo.getByTestId('attack').click();await expect.poll(async()=>(await demoGame(demo))?.core.revision).toBe(first.core.revision+1);await expect(demo.getByTestId('save-status')).toHaveText('已保存');const expected=advance(first,{type:'BATTLE',move:'attack',commandId:'expected-demo',runId:first.core.runId,expectedRevision:first.core.revision});expect(await demoGame(demo)).toEqual(expected);await settings(demo);await expect(demo.getByLabel('文字大小')).toHaveValue('1');await demo.getByLabel('文字大小').selectOption('2');await expect(demo.getByTestId('local-data-status')).toContainText('已保存');expect(await raw(page,'chenyuan-playable-v1')).toEqual(before);expect(await raw(page,'chenyuan-local-experience-v1')).toEqual(local);expect(await page.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'))).toBe(tracking);await expect(page.getByLabel('文字大小')).toHaveValue('1.5');await demo.getByRole('button',{name:'关闭设置'}).click();await demo.getByTestId('demo-return').click();await expect(demo.getByTestId('realm')).toHaveText('炼气');expect(await snapshot(demo)).toEqual(await snapshot(page));expect(await raw(page,'chenyuan-playable-v1')).toEqual(before);}finally{await demo.close();}
});
test('demo reload, reset and typed export/import stay separate from normal saves',async({page})=>{
 const initial=await loaded(page,'battle-talisman');await page.getByTestId('attack').click();await expect.poll(async()=>(await demoGame(page))?.core.revision).toBe(1);const progressed=await demoGame(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(await demoGame(page)).toEqual(progressed);const waiting=page.waitForEvent('download');await page.getByRole('button',{name:'导出存档',exact:true}).click();const file=await waiting,text=fs.readFileSync((await file.path())!,'utf8'),saved=JSON.parse(text);expect(saved.format).toBe('chenyuan-demo-save');expect(saved.game).toEqual(progressed);
 page.once('dialog',d=>d.accept());await page.getByTestId('demo-reset').click();await expect.poll(async()=>(await demoGame(page))?.core.runId).not.toBe(progressed.core.runId);await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(normalized(await demoGame(page))).toEqual(normalized(initial));await settings(page);await expect(page.getByTestId('import')).toBeEnabled();page.once('dialog',d=>d.accept());await page.getByTestId('import').setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await expect(page.getByTestId('settings-save-status')).toHaveText('已保存');await expect.poll(async()=>normalized(await demoGame(page))).toEqual(normalized(progressed));const before=await demoGame(page);await page.getByTestId('import').setInputFiles({name:'ordinary.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(before))});await expect(page.getByTestId('settings-error')).toContainText('演示存档');expect(await demoGame(page)).toEqual(before);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);
 await page.getByRole('button',{name:'关闭设置'}).click();await page.getByTestId('demo-return').click();await expect(page.getByRole('button',{name:'踏入仙途'})).toBeEnabled();await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await expect(page.getByTestId('error')).toBeVisible();await expect(page.getByTestId('realm')).toHaveCount(0);
});
test('unknown, ambiguous, damaged and missing demo nodes never open a normal or demo save',async({page})=>{
 for(const query of ['demo=unknown','demo=','demo=opening&demo=battle-sword']){await page.goto('./?'+query);await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);}
 await page.route('**/demo-nodes/battle-sword.json',route=>route.fulfill({status:200,contentType:'application/json',body:'{}'}));await page.goto('./?demo=battle-sword');await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);await page.unroute('**/demo-nodes/battle-sword.json');await page.route('**/demo-nodes/battle-sword.json',route=>route.fulfill({status:404,body:''}));await page.goto('./?demo=battle-sword');await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);
});
test('a demo seed quota failure keeps the normal database intact and retries one stable import',async({page})=>{
 await start(page);const normal=await raw(page,'chenyuan-playable-v1');await page.addInitScript(()=>{const put=IDBObjectStore.prototype.put;let failed=false;IDBObjectStore.prototype.put=function(...args:any[]){if(!failed&&this.transaction.db.name.startsWith('chenyuan-demo-game-')&&this.name==='full-receipts'){failed=true;throw new DOMException('demo quota probe','QuotaExceededError');}return Reflect.apply(put,this,args);};});await page.goto('./?demo=trial-sword');await expect(page.getByTestId('save-status')).toHaveText('保存待确认');await expect(page.getByTestId('retry')).toBeEnabled();expect(await demoGame(page)).toBeNull();expect(await raw(page,'chenyuan-playable-v1')).toEqual(normal);await page.getByTestId('retry').click();await expect(page.getByTestId('trial-review-entry')).toBeEnabled();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(await raw(page,'chenyuan-playable-v1')).toEqual(normal);const db=(await databases(page)).find(d=>d.name?.startsWith('chenyuan-demo-game-'))!.name!;expect((await raw(page,db))['full-receipts'].keys).toHaveLength(1);
});
test('demo storage denial offers an explicit scoped reread without falling back to the normal Game',async({page})=>{
 await start(page);const normal=await raw(page,'chenyuan-playable-v1');await page.addInitScript(()=>{const open=IDBFactory.prototype.open;(window as any).__denyDemo=true;IDBFactory.prototype.open=function(name,...args:any[]){if((window as any).__denyDemo&&name.startsWith('chenyuan-demo-game-'))throw new DOMException('demo denied probe','SecurityError');return Reflect.apply(open,this,[name,...args]);};});await page.goto('./?demo=opening');await expect(page.getByTestId('error')).toBeVisible();await expect(page.getByRole('button',{name:'踏入仙途'})).toHaveCount(0);expect(await raw(page,'chenyuan-playable-v1')).toEqual(normal);await page.evaluate(()=>(window as any).__denyDemo=false);await page.getByTestId('reload-storage').click();await expect(page.getByTestId('leave')).toBeEnabled();expect(await raw(page,'chenyuan-playable-v1')).toEqual(normal);
});
test('demo menus and four viewport screenshots retain a visible scope and playable controls at 150 percent',async({page},info)=>{
 for(const [width,height,id,target]of [[1280,720,'opening','leave'],[1440,900,'trial-sword','trial-review-entry'],[1920,1080,'ending-talisman','ending-depart'],[390,844,'battle-sword','attack']]as const){await page.setViewportSize({width,height});await loaded(page,id);const before=await demoGame(page);await settings(page);await page.getByLabel('文字大小').selectOption('1.5');await expect(page.getByTestId('local-data-status')).toContainText('已保存');await page.getByRole('button',{name:'关闭设置'}).click();const button=page.getByTestId(target);await expect(button).toBeEnabled();await button.focus();await expect(button).toBeFocused();expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);expect(await demoGame(page)).toEqual(before);const marker=page.getByTestId('demo-persistent-label');await expect(marker).toContainText('演示存档');const box=await marker.boundingBox();expect(box!.y).toBeGreaterThanOrEqual(0);expect(box!.y+box!.height).toBeLessThanOrEqual(height);await page.screenshot({path:info.outputPath('demo-'+width+'.png')});await page.getByRole('button',{name:'切换演示节点',exact:true}).click();await expect(page.locator('#demo-menu-title')).toBeFocused();await expect(page.getByTestId('demo-node-opening')).toBeVisible();await page.keyboard.press('Escape');await expect(page.getByRole('button',{name:'切换演示节点',exact:true})).toBeFocused();}
});
test('two first-load demo tabs share one seed receipt and sync their own committed turn',async({page,context})=>{
 const other=await context.newPage();try{await Promise.all([page.goto('./?demo=battle-sword'),other.goto('./?demo=battle-sword')]);for(const tab of[page,other]){await expect(tab.getByTestId('demo-badge')).toBeVisible();await expect.poll(()=>demoGame(tab)).not.toBeNull();await expect(tab.getByTestId('save-status')).not.toContainText('保存中');if(await tab.getByTestId('save-status').textContent()==='保存待确认'){await expect(tab.getByTestId('error')).toBeVisible();await tab.reload();await expect(tab.getByTestId('save-status')).toHaveText('已保存');}}const before=await demoGame(page);expect(await demoGame(other)).toEqual(before);const db=(await databases(page)).find(d=>d.name?.startsWith('chenyuan-demo-game-'))!.name!;expect((await raw(page,db))['full-receipts'].keys).toHaveLength(1);await page.getByTestId('attack').click();await expect.poll(async()=>(await demoGame(other))?.core.revision).toBe(1);await expect.poll(()=>other.getByTestId('save-status').textContent()).toBe('已保存');expect((await raw(page,db))['full-receipts'].keys).toHaveLength(2);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);}finally{await other.close();}
});
test('demo trial entries create real repeatable complete checkpoints rather than importing invented ones',async({page})=>{
 const initial=await loaded(page,'trial-sword');for(let attempt=0;attempt<2;attempt++){await page.getByTestId('trial-review-entry').click();await page.getByTestId('trial-confirm-entry').click();await expect(page.getByTestId('answer-accept')).toBeEnabled();await page.getByTestId('answer-accept').click();await expect(page.getByTestId('flee')).toBeEnabled();await page.getByTestId('flee').click();await expect(page.getByTestId('trial-restore-open')).toBeEnabled();await page.getByTestId('trial-restore-open').click();await page.getByTestId('trial-restore-confirm').click();await expect(page.getByTestId('trial-review-entry')).toBeEnabled();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(normalized(await demoGame(page))).toEqual(normalized(initial));}expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);
});
test('both demo endings commit through the real confirmation and a node reset never touches normal progress',async({page})=>{
 await loaded(page,'ending-talisman');for(const ending of ['transmit','depart']){await page.getByTestId('ending-'+ending).click();await page.getByTestId('ascension-confirm').click();await expect(page.getByTestId('life-title')).toContainText(ending==='transmit'?'留道传承':'独赴上界');await expect(page.getByTestId('save-status')).toHaveText('已保存');const saved=await demoGame(page);expect(saved.status).toBe('ascended');expect(saved.ending).toBe(ending);await expect(page.getByTestId('ending-'+ending)).toHaveCount(0);if(ending==='transmit'){page.once('dialog',d=>d.accept());await page.getByTestId('demo-reset').click();await expect(page.getByTestId('ending-depart')).toBeEnabled();}}expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);
});

import {test,expect,type Page,type TestInfo,type Locator} from '@playwright/test';
import {writeFile} from 'node:fs/promises';
import {readFileSync} from 'node:fs';
import {newGame,advance} from '../../src/full/engine.ts';
import {driver} from '../../tests/full-route.mjs';
import {demoCatalog} from '../../src/demo.ts';
import {guideCatalog} from '../src/guidance';
import type {Game} from '../../src/full/types.ts';
import {useJourneyClock,snapshot,activitySnapshot as activity} from './support';

test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const gameDB='chenyuan-playable-v1',localDB='chenyuan-local-experience-v1';
const errors=new WeakMap<Page,string[]>();
function listen(page:Page){if(errors.has(page))return;const rows:string[]=[];errors.set(page,rows);page.on('pageerror',e=>rows.push(e.message));}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({context},info)=>{for(const page of context.pages())if(!page.isClosed()){
  await page.evaluate(()=>{const w=window as any;w.__m03ReleaseWrite?.();w.__m03RestoreFile?.();w.__m03ControlObserver?.disconnect();});
  await info.attach('control-browser-errors',{body:JSON.stringify(errors.get(page)??[]),contentType:'application/json'});
  expect(errors.get(page)??[]).toEqual([]);
}});
async function evidence(info:TestInfo,name:string,data:unknown){const path=info.outputPath(name+'.json');await writeFile(path,JSON.stringify(data,null,2)+'\n');await info.attach(name,{path,contentType:'application/json'});}
async function database(page:Page,name=gameDB){return page.evaluate(name=>new Promise<any>((resolve,reject)=>{
  const q=indexedDB.open(name);q.onupgradeneeded=()=>{q.transaction!.abort();reject(new Error('Readonly UI observation cannot create '+name));};q.onerror=()=>reject(q.error);
  q.onsuccess=()=>{const db=q.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};
    for(const key of db.objectStoreNames){rows[key]=[];const read=tx.objectStore(key).openCursor();read.onsuccess=()=>{if(read.result){rows[key].push({key:read.result.key,value:read.result.value});read.result.continue();}};}
    tx.oncomplete=()=>{const version=db.version;db.close();resolve({version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};
}),name);}
const current=(raw:any)=>raw.rows['full-state'].find((r:any)=>r.key==='current')?.value??null;
async function settings(page:Page){if(!await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'设置',exact:true}).click();await expect(page.getByRole('dialog',{name:'行旅设置',exact:true})).toBeVisible();}
async function closeSettings(page:Page){if(await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'关闭设置',exact:true}).click();}
async function localPanel(page:Page){await settings(page);const box=page.getByTestId('local-records-panel');if(!await box.evaluate(n=>(n as HTMLDetailsElement).open))await box.locator(':scope>summary').click();await expect(page.getByTestId('local-recording')).toBeEnabled();}
async function boot(page:Page,virtual=true){if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.getByTestId('save-status')).toHaveText('尚无存档',{timeout:15000});
  await localPanel(page);if(!await page.getByTestId('local-recording').isChecked())await page.getByTestId('local-recording').check();await expect.poll(async()=>{const r=await database(page,localDB);return r.rows.meta.find((x:any)=>x.key==='state')?.value.preferences.recording;}).toBe(true);await closeSettings(page);
}
async function controlClock(page:Page){await expect(page.getByTestId('action-execution')).toBeVisible();await page.clock.runFor(600);}
async function quietFeedback(page:Page){await page.clock.runFor(32);await page.clock.fastForward(1600);await page.clock.runFor(32);await expect(page.getByTestId('hub-pulse')).toHaveCount(0);await expect(page.getByTestId('action-motion')).toHaveCount(0);}
async function create(page:Page,name='界面控制客',virtual=true){await page.getByLabel('你的道号',{exact:true}).fill(name);await page.getByRole('button',{name:'踏入仙途',exact:false}).click();if(virtual)await controlClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');const game=await snapshot(page);expect(game).toEqual(newGame(name,game.core.runId));return game as Game;}
async function chooseDialog(page:Page,accept:boolean,operation:()=>Promise<unknown>){const dialog=page.waitForEvent('dialog',{timeout:8000}),acting=operation(),opened=await dialog;const message=opened.message();if(accept)await opened.accept();else await opened.dismiss();await acting;expect(message).not.toBe('');return message;}
async function importWelcome(page:Page,fixture:Game){await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'lawful-control-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await controlClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');const after=await snapshot(page);expectImported(fixture,after);await quietFeedback(page);return after as Game;}
function expectImported(fixture:Game,actual:Game){const expected=structuredClone(fixture);expected.core.runId=actual.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=actual.core.runId+':'+expected.core.activeEvent.id;expect(actual).toEqual(expected);}
async function recordFor(page:Page,kind:string,run:string){let found:any[]=[];await expect.poll(async()=>{const raw=await database(page,localDB);found=raw.rows.events.filter((r:any)=>r.value.data.observation.kind===kind&&r.value.data.observation.runId===run);return found.length;}).toBe(1);return found[0].value.data.observation;}
async function holdWrite(page:Page){await page.evaluate(()=>new Promise<void>((resolve,reject)=>{
  const q=indexedDB.open('chenyuan-playable-v1');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction('full-state','readwrite');let held=true,ready=false;const w=window as any;w.__m03ReleaseWrite=()=>held=false;
    const read=()=>{const r=tx.objectStore('full-state').get('current');r.onsuccess=()=>{w.__m03HeldGame=r.result??null;if(!ready){ready=true;resolve();}if(held)read();};};read();tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};
}));}
async function observeControls(page:Page){await page.evaluate(()=>{const w=window as any,seen=new Set<string>(),rows:any[]=[];
  const visit=(node:Node)=>{if(!(node instanceof Element))return;for(const el of node.matches('[data-testid=hub-pulse]')?[node]:node.querySelectorAll('[data-testid=hub-pulse]')){const key=el.getAttribute('data-receipt');if(key&&!seen.has(key)){seen.add(key);rows.push({key,operation:el.getAttribute('data-operation'),text:el.textContent});}}};
  const observer=new MutationObserver(changes=>{for(const c of changes)for(const n of c.addedNodes)visit(n);});observer.observe(document.body,{subtree:true,childList:true});w.__m03ControlRows=rows;w.__m03ControlObserver=observer;
});}
async function picture(page:Page,info:TestInfo,name:string,selector:string){const geometry=await page.locator(selector).evaluateAll(nodes=>nodes.map(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n),dialog=n.closest('dialog[open]'),d=dialog?.getBoundingClientRect();return{text:n.textContent,rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom,height:r.height},font:parseFloat(s.fontSize),opacity:s.opacity,clip:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,dialog:d?{left:d.left,right:d.right,top:d.top,bottom:d.bottom,clientHeight:dialog!.clientHeight,scrollHeight:dialog!.scrollHeight}:null};}));await evidence(info,name+'-geometry',geometry);await page.screenshot({path:info.outputPath(name+'.png')});
  expect(await page.evaluate(()=>document.documentElement.scrollHeight)).toBeLessThanOrEqual(900);for(const r of geometry){expect(r.rect.left).toBeGreaterThanOrEqual(0);expect(r.rect.right).toBeLessThanOrEqual(1440);expect(r.rect.top).toBeGreaterThanOrEqual(0);expect(r.rect.bottom).toBeLessThanOrEqual(900);expect(r.clip,r.text??'').toBe(false);}
}
async function hit(control:Locator){await expect(control).toBeInViewport({ratio:1});expect(await control.evaluate(n=>{const r=n.getBoundingClientRect(),top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return{height:r.height,hit:top===n||!!top&&n.contains(top)};})).toMatchObject({hit:true});expect(await control.evaluate(n=>n.getBoundingClientRect().height)).toBeGreaterThanOrEqual(44);}
